import java.util.concurrent.ConcurrentHashMap;

public class ConcurrentCache {
    private final ConcurrentHashMap<String, Expensive> cache = new ConcurrentHashMap<>();

    // WRONG: check-then-act races. Two threads can both miss and both build.
    public Expensive broken(String k) {
        Expensive v = cache.get(k);
        if (v == null) {
            v = build(k);          // expensive, possibly duplicated
            cache.put(k, v);
        }
        return v;
    }

    // RIGHT: one atomic install per key. Mapping fn must be short and non-blocking.
    public Expensive get(String k) {
        return cache.computeIfAbsent(k, this::build);
    }

    // Atomic counter without external locking.
    private final ConcurrentHashMap<String, Long> counts = new ConcurrentHashMap<>();
    public void count(String k) {
        counts.merge(k, 1L, Long::sum);
    }

    private Expensive build(String k) { return new Expensive(k); }
    record Expensive(String k) {}
}

import java.util.concurrent.*;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class Pipeline {
    // Bounded queue: full queue blocks producer -> natural backpressure.
    // Trade-off: you must decide timeout / rejection, or producers stall.
    private final BlockingQueue<Task> queue = new ArrayBlockingQueue<>(1000);
    // Reads >> writes: listeners are iterated constantly, mutated rarely.
    private final List<Listener> listeners = new CopyOnWriteArrayList<>();

    public void publish(Task t) throws InterruptedException {
        // Never put() unbounded work blindly; offer with timeout surfaces overload.
        boolean accepted = queue.offer(t, 100, TimeUnit.MILLISECONDS);
        if (!accepted) throw new RejectedExecutionException("queue full");
    }

    public void consumeLoop() throws InterruptedException {
        while (!Thread.currentThread().isInterrupted()) {
            Task t = queue.take(); // parks when empty, no spin, no size check
            for (Listener l : listeners) l.onTask(t); // snapshot-safe, never throws
        }
    }

    interface Listener { void onTask(Task t); }
    record Task(String id) {}
}
